def ok(seq, n=5, cap=3):
    st, nxt, peak = [], 1, 0
    for x in seq:
        while (not st or st[-1] != x) and nxt <= n:
            st.append(nxt); nxt += 1; peak = max(peak, len(st))
        if st and st[-1] == x: st.pop()
        else: return False
    return peak <= cap
